import argparse
import gzip
import hashlib
import json
import signal
from dataclasses import dataclass, replace
from datetime import datetime, timezone
from io import StringIO
from pathlib import Path

import numpy as np
import pandas as pd
import yaml
from pandas.tseries.holiday import (
    AbstractHolidayCalendar,
    GoodFriday,
    Holiday,
    USLaborDay,
    USMartinLutherKingJr,
    USMemorialDay,
    USPresidentsDay,
    USThanksgivingDay,
    nearest_workday,
    sunday_to_monday,
)
from scipy.linalg import solve_triangular
from scipy.optimize import nnls


ROOT = Path(__file__).resolve().parent
SESSIONS_PER_YEAR = 252
TIME_LIMIT_SECONDS = 570
PRICE_ADJUSTMENT = (
    "yfinance auto_adjust=True, split- and dividend-adjusted close "
    "(label of the snapshot's adjustment convention; the run itself does not call yfinance)"
)
TIMESTAMP_PREFIX = "# DATA_FETCHED_AT: "


class NyseHolidays(AbstractHolidayCalendar):
    rules = [
        Holiday("New Year's Day", month=1, day=1, observance=sunday_to_monday),
        USMartinLutherKingJr,
        USPresidentsDay,
        GoodFriday,
        USMemorialDay,
        Holiday("Juneteenth", month=6, day=19, start_date="2022-01-01", observance=nearest_workday),
        Holiday("Independence Day", month=7, day=4, observance=nearest_workday),
        USLaborDay,
        USThanksgivingDay,
        Holiday("Christmas Day", month=12, day=25, observance=nearest_workday),
    ]


def nyse_sessions(start, end):
    if start < pd.Timestamp("2008-01-01") or end > pd.Timestamp("2024-12-31"):
        raise ValueError("The NYSE calendar covers 2008 through 2024")
    holidays = NyseHolidays().holidays(start, end)
    # Hurricane Sandy and the national day of mourning for George H. W. Bush.
    special_closures = pd.to_datetime(["2012-10-29", "2012-10-30", "2018-12-05"])
    return pd.bdate_range(start, end).difference(holidays.union(special_closures))


@dataclass(frozen=True)
class Model:
    execution_lag_sessions: int
    lookback_sessions: int
    cost_bps: float
    slippage_bps: float
    cash_buffer_bps: float
    estimator: str
    noise_gate: float
    channel_boundary: float
    channel_weights: tuple[float, float, float]
    minimum_correlation_eigenvalue: float

    def __post_init__(self):
        if type(self.execution_lag_sessions) is not int or self.execution_lag_sessions < 1:
            raise ValueError("execution_lag_sessions must be a positive integer")
        if type(self.lookback_sessions) is not int or self.lookback_sessions < 2:
            raise ValueError("lookback_sessions must be an integer of at least two")
        if not (0 <= self.noise_gate < self.channel_boundary < np.inf):
            raise ValueError("Require 0 <= noise_gate < channel_boundary")
        if len(self.channel_weights) != 3 or not all(0 <= w <= 1 for w in self.channel_weights):
            raise ValueError("Require three channel weights in [0, 1]")
        if not 0 < self.minimum_correlation_eigenvalue <= 1:
            raise ValueError("The correlation eigenvalue floor must be in (0, 1]")
        if not (self.cost_bps >= 0 and self.slippage_bps >= 0 and self.rate < 1):
            raise ValueError("Costs and slippage must be nonnegative and total under 10000 bps")
        if not 0 < self.cash_buffer_bps < 10_000:
            raise ValueError("The cash buffer must be between 0 and 10000 bps")
        if self.estimator not in {"atomic_iq", "sample"}:
            raise ValueError(f"Unknown estimator {self.estimator!r}")

    @property
    def rate(self):
        return (self.cost_bps + self.slippage_bps) / 10_000


def validate_prices(prices, symbols, sessions):
    if prices.empty or not set(symbols).issubset(prices.columns):
        raise ValueError("Missing required columns or dates in the price panel")
    dates = prices.index
    if not dates.is_monotonic_increasing or dates.has_duplicates:
        raise ValueError("Price dates must be unique and increasing")
    missing = sessions.difference(dates)
    unexpected = dates.difference(sessions)
    if len(missing):
        raise ValueError(f"Missing NYSE price session {missing[0].date()}")
    if len(unexpected):
        raise ValueError(f"Unexpected NYSE price session {unexpected[0].date()}")
    values = prices.loc[:, symbols].to_numpy()
    bad = ~np.isfinite(values) | (values <= 0)
    if bad.any():
        row, col = np.argwhere(bad)[0]
        raise ValueError(f"Missing or invalid adjusted close for {symbols[col]} on {dates[row].date()}")


def load_config(config_path="config.yaml"):
    with open(config_path, encoding="utf-8") as file:
        return yaml.safe_load(file)


def load_prices(config, config_path, universe, benchmark, risk_free, start, end, sessions):
    symbols = [benchmark, risk_free, *universe]
    data = config.get("data") or {}
    blob = data.get("market_snapshot_gzip")
    expected_digest = data.get("market_snapshot_sha256")
    if not isinstance(blob, (bytes, bytearray)) or not expected_digest:
        raise ValueError("config.data must carry market_snapshot_gzip and market_snapshot_sha256")
    snapshot = gzip.decompress(bytes(blob))
    digest = hashlib.sha256(snapshot).hexdigest()
    if digest != expected_digest:
        raise ValueError(
            f"SHA-256 mismatch for the Yahoo Finance snapshot in {Path(config_path).name}: {digest}."
        )
    text = snapshot.decode("utf-8")
    header, sep, body = text.partition("\n")
    if not header.startswith(TIMESTAMP_PREFIX) or not sep:
        raise ValueError("Missing cache timestamp")
    fetched_at = header.removeprefix(TIMESTAMP_PREFIX).strip()
    if datetime.fromisoformat(fetched_at).utcoffset() is None:
        raise ValueError("Cache timestamp must have a time zone")
    input_digest = hashlib.sha256(body.encode("utf-8")).hexdigest()
    prices = pd.read_csv(StringIO(body), index_col="date", parse_dates=["date"])
    prices.index = prices.index.astype("datetime64[ns]")
    validate_prices(prices, symbols, sessions)
    provenance = {
        "path": Path(config_path).name,
        "key": "data.market_snapshot_gzip",
        "sha256": digest,
    }
    print(
        "Data source: Yahoo Finance snapshot embedded in config under data.market_snapshot_gzip "
        f"(decompressed sha256 {digest}); daily split- and dividend-adjusted closes. "
        "The script does not call yfinance or read data_cache."
    )
    print(f"DATA_FETCHED_AT: {fetched_at}")
    print(f"PRICE_ADJUSTMENT: {PRICE_ADJUSTMENT}")
    print(f"Input SHA-256: {input_digest}")
    print(f"DATA_SHA256: {digest}")
    print(f"MARKET_DATA_SNAPSHOT: {json.dumps(provenance, allow_nan=False)}")
    print(f"Price sessions: {len(prices)} ({prices.index[0].date()} to {prices.index[-1].date()})")
    return prices, fetched_at


def atomic_correlation(window, vols, model):
    n = len(vols)
    left, right = np.triu_indices(n)
    off_diagonal = left != right
    pair_scale = np.maximum(vols[left], vols[right])
    first = window[:, left]
    second = window[:, right]
    informative = np.minimum(np.abs(first), np.abs(second)) > model.noise_gate * pair_scale
    first_tail = np.abs(first) > model.channel_boundary * pair_scale
    second_tail = np.abs(second) > model.channel_boundary * pair_scale
    direction = np.sign(first) * np.sign(second)

    identity = np.eye(n)
    squeezed = (1.0 - sum(model.channel_weights)) * identity
    for weight, channel in zip(
        model.channel_weights,
        (~(first_tail | second_tail), first_tail ^ second_tail, first_tail & second_tail),
    ):
        events = informative & channel
        counts = events.sum(axis=0)
        # Each atom contributes one unit to each involved diagonal.
        mass = np.bincount(left, weights=counts, minlength=n)
        mass += np.bincount(right[off_diagonal], weights=counts[off_diagonal], minlength=n)
        signed_counts = (direction * events).sum(axis=0)[off_diagonal]
        rows = left[off_diagonal]
        cols = right[off_diagonal]
        scale = np.sqrt(mass[rows] * mass[cols])
        correlations = np.divide(signed_counts, scale, out=np.zeros_like(scale), where=scale > 0)
        matrix = identity.copy()
        matrix[rows, cols] = matrix[cols, rows] = correlations
        squeezed += weight * matrix
    return squeezed


def estimate_covariance(window, model):
    vols = window.std(axis=0, ddof=1)
    if not np.isfinite(vols).all() or (vols <= 0).any():
        raise ValueError("Every asset needs finite, positive volatility in the estimation window")
    if model.estimator == "sample":
        correlation = np.eye(1) if len(vols) == 1 else np.corrcoef(window, rowvar=False)
    else:
        correlation = atomic_correlation(window, vols, model)

    # Paper equation (20). Mixing with identity preserves the unit diagonal.
    smallest = np.linalg.eigvalsh(correlation)[0]
    floor = model.minimum_correlation_eigenvalue
    if smallest < floor:
        phi = (floor - smallest) / (1 - smallest)
        correlation = (1 - phi) * correlation + phi * np.eye(len(vols))
    return correlation * np.outer(vols, vols)


def tangency_weights(excess_mean, covariance):
    if excess_mean.max() <= 0:
        # With all means nonpositive, the triangle inequality puts an optimum at a vertex.
        weights = np.zeros_like(excess_mean)
        weights[np.argmax(excess_mean / np.sqrt(np.diag(covariance)))] = 1.0
        return weights

    # The nonnegative quadratic problem gives the tangency direction up to scale.
    root = np.linalg.cholesky(covariance)
    rhs = solve_triangular(root, excess_mean, lower=True)
    direction, _ = nnls(root.T, rhs)
    if direction.sum() <= 0:
        raise RuntimeError("Tangency optimization returned no positive weights")
    return direction / direction.sum()


def make_targets(stock_returns, risk_free_returns, sessions, start, model):
    # Prices have already been checked against these exchange sessions.
    months = sessions.to_period("M")
    month_ends = np.flatnonzero(months[:-1] != months[1:])
    earliest_execution = sessions.searchsorted(start)
    samples = stock_returns.to_numpy()
    risk_free = risk_free_returns.to_numpy()
    targets = {}
    for close in month_ends:
        execution = close + model.execution_lag_sessions
        if close < model.lookback_sessions or not earliest_execution <= execution < len(sessions):
            continue
        window = slice(close - model.lookback_sessions + 1, close + 1)
        sample = samples[window]
        excess_mean = sample.mean(axis=0) - risk_free[window].mean()
        targets[sessions[execution]] = tangency_weights(excess_mean, estimate_covariance(sample, model))
    return targets


def size_rebalance(target, positions, sizing_close, previous_value, invested_fraction, day):
    target = np.asarray(target, dtype=float)
    if (
        target.shape != positions.shape
        or not np.isfinite(target).all()
        or (target < 0).any()
        or target.sum() > 1.0 + 1e-12
    ):
        raise ValueError(f"Invalid long-only target for {day.date()}")

    sized_positions = previous_value * invested_fraction * target / sizing_close
    sized_changes = sized_positions - positions
    sized_changes.setflags(write=False)
    return sized_positions, sized_changes


def settle_fill(sized_changes, cash, fill_close, rate, day):
    sale_value = np.maximum(-sized_changes, 0.0) @ fill_close
    buy_value = np.maximum(sized_changes, 0.0) @ fill_close
    available_cash = cash + sale_value * (1.0 - rate)
    purchase_cost = buy_value * (1.0 + rate)
    cash_after = available_cash - purchase_cost
    if not np.isfinite(cash_after) or cash_after < 0.0:
        raise RuntimeError(
            f"Fixed quantities on {day.date()} cannot settle with nonnegative cash. "
            f"Cash including net sales {available_cash:.8g}, "
            f"purchases including costs {purchase_cost:.8g}, remaining cash {cash_after:.8g}."
        )
    return cash_after, sale_value + buy_value


def simulate(asset_prices, targets, model, start):
    positions = np.zeros(asset_prices.shape[1])
    cash = 1.0
    closes = asset_prices.to_numpy()
    first = asset_prices.index.searchsorted(start)
    if first == 0:
        raise ValueError("Backtest needs a close before the first reported session")
    dates = asset_prices.index[first:]
    invested_fraction = 1.0 - model.cash_buffer_bps / 10_000
    daily_results = []
    for offset, day in enumerate(dates, start=first):
        sizing_close = closes[offset - 1]
        previous_value = cash + positions @ sizing_close
        turnover, trades = 0.0, 0
        target = targets.get(day)
        if target is not None:
            sized_positions, sized_changes = size_rebalance(
                target, positions, sizing_close, previous_value, invested_fraction, day
            )
            # The current close enters only after quantities are fixed.
            fill_close = closes[offset]
            cash_after, traded = settle_fill(sized_changes, cash, fill_close, model.rate, day)
            turnover = traded / (cash + positions @ fill_close)
            trades = int(np.count_nonzero(sized_changes))
            positions, cash = sized_positions, cash_after
        closing_value = cash + positions @ closes[offset]
        daily_results.append((closing_value / previous_value - 1.0, turnover, trades, cash / closing_value))
    return pd.DataFrame(
        daily_results, index=dates, columns=["returns", "turnover", "n_trades", "cash_fraction"]
    )


def execution_summary(daily_results, scheduled_rebalances):
    fill_cash = daily_results.loc[daily_results["n_trades"] > 0, "cash_fraction"]
    return {
        "scheduled_rebalances": scheduled_rebalances,
        "fill_sessions": len(fill_cash),
        "scheduled_sessions_without_fills": scheduled_rebalances - len(fill_cash),
        "min_post_fill_cash_fraction": None if fill_cash.empty else float(fill_cash.min()),
        # A shortfall raises before the run can produce a summary.
        "cash_shortfalls": 0,
    }


def sample_volatility(returns):
    # Floating-point mean subtraction can give constant returns a tiny nonzero standard deviation.
    if len(returns) > 1 and returns.eq(returns.iloc[0]).all():
        return 0.0
    return returns.std(ddof=1)


def metrics(daily_results, risk_free_returns):
    gains = daily_results["returns"]
    if gains.empty:
        return {
            "cagr": None, "ann_vol": None, "sharpe": None, "sharpe_excess": None,
            "max_drawdown": None, "total_return": None, "turnover": None, "n_trades": 0,
        }
    excess = gains - risk_free_returns.loc[gains.index]
    volatility = sample_volatility(gains)
    excess_volatility = sample_volatility(excess)
    years = len(gains) / SESSIONS_PER_YEAR
    cumulative = np.r_[1.0, (1.0 + gains).cumprod()]
    annualizer = np.sqrt(SESSIONS_PER_YEAR)
    return {
        "cagr": float(cumulative[-1] ** (1 / years) - 1),
        "ann_vol": float(volatility * annualizer) if np.isfinite(volatility) else None,
        "sharpe": float(gains.mean() / volatility * annualizer) if volatility > 0 else None,
        "sharpe_excess": float(excess.mean() / excess_volatility * annualizer) if excess_volatility > 0 else None,
        "max_drawdown": float(np.min(cumulative / np.maximum.accumulate(cumulative) - 1)),
        "total_return": float(cumulative[-1] - 1),
        "turnover": float(daily_results["turnover"].sum() / years),
        "n_trades": int(daily_results["n_trades"].sum()),
    }


def period_metrics(daily_results, risk_free_returns, is_end):
    return {
        "is": metrics(daily_results.loc[:is_end], risk_free_returns),
        "oos": metrics(daily_results.loc[daily_results.index > is_end], risk_free_returns),
        "full": metrics(daily_results, risk_free_returns),
    }


def main():
    parser = argparse.ArgumentParser(description="551 squeezed covariance matrix estimation")
    parser.add_argument("--config", default="config.yaml", help="Path to config file")
    parser.add_argument("--refresh", action="store_true", help="Rejected: this run uses the embedded snapshot only")
    args = parser.parse_args()
    if args.refresh:
        raise SystemExit("This run reads the embedded Yahoo Finance snapshot only; --refresh is not supported.")

    config = load_config(args.config)
    print(f"Run directory: {Path.cwd()}")
    print(f"RUN_DIRECTORY: {Path.cwd()}")
    print(f"RUN_STARTED_AT: {datetime.now().astimezone().isoformat(timespec='milliseconds')}")
    file_sha = hashlib.sha256(Path(__file__).read_bytes()).hexdigest()
    print(f"Strategy SHA-256: {file_sha}")
    print(f"STRATEGY_SHA256: {file_sha}")
    print(f"CONFIG_SHA256: {hashlib.sha256(Path(args.config).read_bytes()).hexdigest()}")
    params = {key: value for key, value in config.items() if key != "data"}
    effective_config = yaml.safe_dump(params, sort_keys=True).encode("utf-8")
    print(f"Effective config SHA-256: {hashlib.sha256(effective_config).hexdigest()}")

    model = Model(**{key: config[key] for key in Model.__dataclass_fields__})
    cases = {name: replace(model, **changes) for name, changes in config["robustness"].items()}
    universe = config["universe"]
    benchmark = config["benchmark"]
    risk_free = config["risk_free_proxy"]
    symbols = [*universe, benchmark, risk_free]
    if not universe or len(set(symbols)) != len(symbols):
        raise ValueError("The universe, benchmark and risk-free symbols must be distinct")
    data_start, start, is_end, end = (
        pd.Timestamp(config[key]) for key in ("data_start", "backtest_start", "is_end", "backtest_end")
    )
    if not data_start < start < is_end < end:
        raise ValueError("Require data_start < backtest_start < is_end < backtest_end")

    sessions = nyse_sessions(data_start, end)
    prices, fetched_at = load_prices(config, args.config, universe, benchmark, risk_free, data_start, end, sessions)
    returns = prices.pct_change(fill_method=None)
    stock_returns = returns[universe]
    risk_free_returns = returns[risk_free]
    stock_prices = prices[universe]
    evaluation = stock_prices.loc[start:].index
    if evaluation.empty:
        raise ValueError("No NYSE sessions in the requested backtest dates")

    # Evaluate alternatives with inputs bounded by the IS end date.
    is_sessions = sessions[sessions <= is_end]
    is_stocks = stock_returns.loc[:is_end]
    is_risk_free = risk_free_returns.loc[:is_end]
    robustness = {}
    robustness_execution = {}
    combos_tried = 1
    for name, case in cases.items():
        targets = make_targets(is_stocks, is_risk_free, is_sessions, start, case)
        daily_results = simulate(stock_prices.loc[:is_end], targets, case, start)
        robustness[name] = metrics(daily_results, is_risk_free)
        robustness_execution[name] = execution_summary(daily_results, len(targets))
        combos_tried += 1

    targets = make_targets(stock_returns, risk_free_returns, sessions, start, model)
    daily_results = simulate(stock_prices, targets, model, start)
    strategy_metrics = period_metrics(daily_results, risk_free_returns, is_end)
    benchmark_targets = {min(targets, default=evaluation[0]): np.ones(1)}
    benchmark_daily = simulate(prices[[benchmark]], benchmark_targets, model, start)
    comparison = period_metrics(benchmark_daily, risk_free_returns, is_end)

    print(f"PARAM_COMBOS_TRIED: {combos_tried}")
    print("ROBUSTNESS (IS ONLY)")
    print("default:", json.dumps(strategy_metrics["is"], allow_nan=False))
    for name, values in robustness.items():
        print(f"{name}:", json.dumps(values, allow_nan=False))
    for period in ("is", "oos", "full"):
        print(f"{period.upper()}:", json.dumps(strategy_metrics[period], allow_nan=False))
        print(f"BENCHMARK {benchmark} {period.upper()}:", json.dumps(comparison[period], allow_nan=False))

    execution = {
        "default_full": execution_summary(daily_results, len(targets)),
        "benchmark_full": execution_summary(benchmark_daily, len(benchmark_targets)),
        "robustness_is": robustness_execution,
    }
    print("EXECUTION_DIAGNOSTICS: " + json.dumps(execution, allow_nan=False))

    result = {
        "strategy": config["strategy"],
        "data_range": {
            "start": evaluation[0].date().isoformat(),
            "end": evaluation[-1].date().isoformat(),
        },
        **strategy_metrics,
        "benchmark": {"name": benchmark, **comparison},
    }
    print("RESULTS_JSON: " + json.dumps(result, allow_nan=False))


def time_limit(_signum, _frame):
    raise SystemExit(f"Backtest exceeded its {TIME_LIMIT_SECONDS}-second runtime limit")


if __name__ == "__main__":
    signal.signal(signal.SIGALRM, time_limit)
    signal.alarm(TIME_LIMIT_SECONDS)
    try:
        main()
    except (ValueError, RuntimeError, OSError) as error:
        raise SystemExit(str(error)) from error
    finally:
        signal.alarm(0)
